"""Deterministic original MyVoice sounds. Standard library only; no sampled media."""
from pathlib import Path
import math,random,wave,struct,json,hashlib
root=Path(__file__).resolve().parents[1]/'assets'/'OfficialPacks';root.mkdir(exist_ok=True)
packs=[('starter','MyVoice Starter','Les essentiels, prêts à jouer.', [('Notification','chime',.7),('Buzzer','buzz',.55),('Correct','up',.8),('Wrong','down',.65),('Drum hit','drum',.45),('Pop','pop',.18),('Whoosh','whoosh',.8),('Impact','impact',.75),('Door knock','knock',.8),('Phone vibration','vibration',1.1)]),('prankster','Prankster','Des surprises et des bruitages décalés.', [('Bubble burst','rasp',.8),('Door slam','slam',.8),('Knocking','knock',1.1),('Pocket buzz','vibration',1.4),('Fake notification','chime',1.0),('Suspicious noise','suspense',1.8),('Squeak','squeak',.65),('Spring','spring',1.0),('Dramatic silence','pause',1.8),('Comedic impact','bonk',.6)]),('memes','Memes','Réactions originales, énergie cartoon.', [('Exaggerated fail','down',1.5),('Awkward pause','pause',1.7),('Cartoon bonk','bonk',.6),('Dramatic sting','sting',1.2),('Tiny applause','clap',1.2),('Confusion','spring',.9),('Really','squeak',.8),('Victory wink','up',1.1)]),('anime-inspired','Anime-Inspired','Magie et énergie, créations originales.', [('Magical sparkle','sparkle',1.4),('Transformation','shimmer',2.0),('Dramatic slash','slash',.8),('Energy charge','charge',1.8),('Cute reaction','cute',.7),('Shocked reaction','shock',.7),('Dramatic hit','impact',1.2),('Futuristic UI','ui',.7),('Comic swoosh','whoosh',.6)])]
manifest=[];sr=48000
for pack_index,(key,title,description,entries) in enumerate(packs):
 folder=root/key;folder.mkdir(exist_ok=True);sounds=[]
 for index,(name,kind,duration) in enumerate(entries):
  seed=pack_index*100+index;rng=random.Random(seed);phase=0;low=0;values=[];n=int(sr*duration)
  for i in range(n):
   t=i/sr;u=t/duration;noise=rng.uniform(-1,1);low=.92*low+.08*noise
   f=400+seed*3;env=min(1,t/.006)*min(1,(duration-t)/.03);v=0
   if kind in ('chime','up','down','ui','cute'):
    steps=[1,1.25,1.5] if kind!='down' else [1.5,1.2,.8];step=min(2,int(u*3));f=(650 if kind=='cute' else 420)*steps[step]+pack_index*21;z=(u*3)%1;v=(math.sin(2*math.pi*f*t)+.22*math.sin(2*math.pi*f*2*t))*math.exp(-z*5)
   elif kind in ('drum','impact','slam','bonk'):
    f=55+180*math.exp(-t*35) if kind!='bonk' else 280+420*math.exp(-t*20);phase+=2*math.pi*f/sr;v=math.sin(phase)*math.exp(-t*7)+noise*.35*math.exp(-t*25)+low*.8*math.exp(-t*9)
   elif kind in ('whoosh','slash'):v=noise*(math.sin(math.pi*u)**3)*(.5 if kind=='slash' else .2)+low*3*math.sin(math.pi*u)
   elif kind=='buzz':v=math.tanh(3*math.sin(2*math.pi*130*t))*.5
   elif kind=='vibration':v=(math.sin(2*math.pi*110*t)+.3*noise)*(.8 if (t%.45)<.28 else 0)
   elif kind=='knock':z=t%.23;v=(math.sin(2*math.pi*190*z)+noise*.7)*math.exp(-z*65)
   elif kind=='pop':phase+=2*math.pi*(150+700*math.exp(-t*65))/sr;v=math.sin(phase)*math.exp(-t*28)
   elif kind in ('squeak','spring','rasp','shock'):f=700+350*math.sin(2*math.pi*(5 if kind=='spring' else 2)*t)*(1-u);phase+=2*math.pi*f/sr;v=math.sin(phase)*math.exp(-u*3);v=v if kind!='rasp' else math.tanh(v*5)*math.sin(2*math.pi*65*t)
   elif kind in ('suspense','sting'):v=sum(math.sin(2*math.pi*f*t) for f in [110,116,165,220])/4*math.exp(-u*(2 if kind=='sting' else .3))
   elif kind=='pause':v=noise*.09*math.exp(-((u-.88)/.025)**2)
   elif kind=='clap':z=t%.13;v=noise*math.exp(-z*100)*(.5+.5*rng.random())
   elif kind in ('sparkle','shimmer'):z=t%.15;f=[1174,1568,1760,2349][int(t/.15)%4];v=(math.sin(2*math.pi*f*t)+.25*math.sin(2*math.pi*f*2.01*t))*math.exp(-z*22)*(.6+.4*math.sin(math.pi*u))
   elif kind=='charge':phase+=2*math.pi*(80+1100*u*u)/sr;v=(math.sin(phase)+noise*.15)*(u**.7)
   values.append(v*env)
  peak=max(abs(v) for v in values) or 1;data=b''.join(struct.pack('<h',round(v/peak*.60*32767)) for v in values)
  filename=f'{index+1:02d}.wav';path=folder/filename
  with wave.open(str(path),'wb') as w:w.setnchannels(1);w.setsampwidth(2);w.setframerate(sr);w.writeframes(data)
  sounds.append({'name':name,'file':key+'/'+filename,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
 manifest.append({'id':key,'title':title,'description':description,'sounds':sounds})
(root/'catalog.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
(root/'LICENSE.txt').write_text('Original procedurally synthesized MyVoice sounds. No external recordings or samples. You may use, modify, redistribute and include these sounds in personal and commercial creations without attribution. No endorsement or exclusive ownership is granted. Generated by publishing/Generate-OfficialSounds.py.\n',encoding='utf-8')
print(f'{sum(len(p[3]) for p in packs)} original PCM sounds generated.')
